{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyPhtGMhHMLc1trn/IAw3b5J"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"trkAP3jZmPrf"},"outputs":[],"source":["#global variables\n","\n","students = []\n","courses = []\n","marks = {}\n","\n","#input\n","\n","def input_students():\n","    num_students = int(input(\"Enter number of students in class: \"))\n","    for i in range(num_students):\n","        print(f\"\\n Student {i + 1} \")\n","        student_id = input(\"ID: \")\n","        name = input(\"Name: \")\n","        dob = input(\"DoB (DD/MM/YYYY): \")\n","        students.append({\"id\": student_id, \"name\": name, \"dob\": dob})\n","\n","def input_courses():\n","    num_courses = int(input(\"Enter number of courses: \"))\n","    for i in range(num_courses):\n","        print(f\"\\n Course {i + 1} \")\n","        course_id = input(\"ID: \")\n","        name = input(\"Name: \")\n","        courses.append({\"id\": course_id, \"name\": name})\n","\n","\n","def input_marks():\n","    if not courses or not students:\n","        print(\"Please enter courses and students first:\")\n","        return\n","\n","#listing\n","\n","    list_courses()\n","    course_id = input(\"\\nSelect course ID to enter marks for: \")\n","\n","    course_exists = any(c[\"id\"] == course_id for c in courses)\n","    if not course_exists:\n","        print(\"Invalid course ID\")\n","        return\n","\n","    if course_id not in marks:\n","        marks[course_id] = {}\n","\n","    print(f\"\\nEnter marks for course: {course_id}:\")\n","    for student in students:\n","        mark = float(\n","            input(f\"Mark for {student['name']} (ID: {student['id']}): \")\n","        )\n","        marks[course_id][student[\"id\"]] = mark\n","\n","\n","def list_courses():\n","    print(\"\\n Course List \")\n","    if not courses:\n","        print(\"No courses available\")\n","        return\n","\n","    for c in courses:\n","        print(f\"ID: {c['id']} | Name: {c['name']}\")\n","\n","\n","def list_students():\n","    print(\"\\n Student List \")\n","    if not students:\n","        print(\"No students available\")\n","        return\n","\n","    for s in students:\n","        print(f\"ID: {s['id']} | Name: {s['name']} | DoB: {s['dob']}\")\n","\n","\n","def show_student_marks():\n","    if not courses:\n","        print(\"No courses available.\")\n","        return\n","\n","    list_courses()\n","    course_id = input(\"\\nEnter course ID to view marks: \")\n","\n","    if course_id not in marks or not marks[course_id]:\n","        print(\"No marks found for this course.\")\n","        return\n","\n","    print(f\"\\n Marks for Course {course_id} c\")\n","    for student in students:\n","        s_id = student[\"id\"]\n","        if s_id in marks[course_id]:\n","            print(f\"ID: {s_id} | Name: {student['name']} | Mark: {marks[course_id][s_id]}\")\n","\n","#control flow and execution\n","\n","def main():\n","    while True:\n","        print(\" STUDENT MARK MANAGEMENT SYSTEM\")\n","        print(\"1. Students\")\n","        print(\"2. Courses\")\n","        print(\"3. Marks\")\n","        print(\"4. List Courses\")\n","        print(\"5. List Students\")\n","        print(\"6. List Marks\")\n","        print(\"7. Get away from this place\")\n","\n","        choice = input(\"Select an option (1-7): \")\n","\n","        if choice == \"1\":\n","            input_students()\n","        elif choice == \"2\":\n","            input_courses()\n","        elif choice == \"3\":\n","            input_marks()\n","        elif choice == \"4\":\n","            list_courses()\n","        elif choice == \"5\":\n","            list_students()\n","        elif choice == \"6\":\n","            show_student_marks()\n","        elif choice == \"7\":\n","            print(\"Exiting program.\")\n","            break\n","        else:\n","            print(\"Invalid selection. Try again.\")\n","\n","\n","if __name__ == \"__main__\":\n","    main()"]}]}